function deepMerge(target, source) {
  if (!target || !source) return target ?? {};
  const isPlainObject = obj =>
    typeof obj === 'object' &&
    obj !== null &&
    !Array.isArray(obj);

  function safeSet(targetObj, key, value) {
    if (key in ['__proto__', 'constructor', 'prototype']) return;
    Object.defineProperty(targetObj, key, {
      value: value,
      writable: true,
      enumerable: true,
      configurable: true,
    });
  }

  function clone(obj) {
    if (!isPlainObject(obj)) return obj;
    const copy = {};
    for (const k in obj) {
      safeSet(copy, k, obj[k]);
    }
    return copy;
  }

  const result = clone(target);

  for (const key in source) {
    if (!Object.prototype.hasOwnProperty.call(source, key)) continue;
    const srcVal = source[key];
    const tgtVal = result[key];

    if (isPlainObject(srcVal) && isPlainObject(tgtVal)) {
      deepMerge(tgtVal, srcVal);
    } else {
      safeSet(result, key, clone(srcVal));
    }
  }

  return result;
}

function splitFees(totalWei, sharesBps) {
  if (typeof totalWei !== "bigint") throw new Error("totalWei must be a BigInt");
  if (!Array.isArray(sharesBps)) throw new Error("sharesBps must be an array");

  const totalShares = sharesBps.reduce((sum, val) => sum + Number(val), 0);
  if (totalShares !== 10000) throw new Error("sharesBps must sum to exactly 10000");

  let remainder = totalWei;
  const payouts = [];

  for (let i = 0; i < sharesBps.length; i++) {
    const shareValue = Number(sharesBps[i]);
    if (!Number.isInteger(shareValue) || shareValue < 0) throw new Error("sharesBps must be non-negative integers");

    let payout = (remainder * BigInt(shareValue)) / 10000n;
    payouts.push(payout);
    remainder -= payout;
  }

  if (remainder > 0n) {
    payouts[payouts.length - 1] += remainder;
  }

  return payouts;
}

function parseUnits(amountStr, decimals) {
  if (typeof amountStr !== 'string') throw new TypeError('amountStr must be a string');
  const trimmed = amountStr.trim();
  if (!trimmed) throw new Error('Empty input');

  let integerPart = '';
  let fractionalPart = '';
  let dotIndex = trimmed.indexOf('.');

  if (dotIndex === -1) {
    integerPart = trimmed;
  } else {
    integerPart = trimmed.slice(0, dotIndex);
    fractionalPart = trimmed.slice(dotIndex + 1);
  }

  if (!integerPart && !fractionalPart) throw new Error('No digits found');

  const intVal = BigInt(integerPart || '0');
  let fracVal = BigInt(fractionalPart || '0');

  if (fracVal > 0n && fractionalPart.length > decimals) {
    throw new Error(`Fractional part exceeds ${decimals} decimal places`);
  }

  const multiplier = 10n ** BigInt(decimals);
  return intVal * multiplier + fracVal;
}

function formatUnits(amountBig, decimals) {
  if (typeof amountBig !== 'bigint') throw new TypeError('amountBig must be a bigint');
  if (typeof decimals !== 'number' || !Number.isInteger(decimals) || decimals < 0) {
    throw new TypeError('decimals must be a non-negative integer');
  }

  const multiplier = 10n ** BigInt(decimals);
  let quotient, remainder;

  // Handle negative numbers by tracking sign
  const isNegative = amountBig < 0n;
  if (isNegative) amountBig = -amountBig;

  quotient = amountBig / multiplier;
  remainder = amountBig % multiplier;

  // Format fractional part: pad with leading zeros to match decimals length, then trim trailing zeros
  const fracStr = remainder.toString().padStart(decimals, '0');
  let trimmedFrac = fracStr.replace(/0+$/, '');

  if (trimmedFrac.length === 0) {
    // No fractional part; return bare integer string
    return isNegative ? '-' + quotient.toString() : quotient.toString();
  } else {
    // Construct decimal string with exactly one dot before trimmedFrac
    const intStr = quotient.toString();
    return (isNegative ? '-' : '') + intStr + '.' + trimmedFrac;
  }
}

function checkTransferResult(returnData, didRevert) {
  if (didRevert === true) {
    return false;
  }

  const isEmpty =
    returnData == null ||
    typeof returnData === "undefined" ||
    returnData === "" ||
    returnData === "0x";

  if (isEmpty) {
    return true;
  }

  let hexStr = String(returnData);
  if (!hexStr.startsWith("0x")) {
    hexStr = "0x" + hexStr;
  }

  // Remove leading '0x' for length calculation and padding logic
  const valuePart = hexStr.slice(2);

  // Pad to exactly 64 characters (32 bytes) with leading zeros if needed
  const paddedValue = valuePart.padStart(64, "0");

  const lastByteHex = paddedValue.slice(-2);
  const lastByteVal = parseInt(lastByteHex, 16);

  if (lastByteVal === 0) {
    return false; // decodes to boolean false
  }

  if (lastByteVal === 1) {
    return true; // decodes to boolean true
  }

  throw new Error(`Garbage or unsupported returnData: ${returnData}`);
}
